Item.method_code:
const { globalCommand, setErrorMessage } = commands;
const canExecute = globalCommand.canExecute();
if (canExecute !== true) {
	return false;
}

const vaultId = aras.getVaultServerID();
if (!vaultId) {
	const message = aras.getResource('', 'item_methods.no_defualt_vault_sever');
	setErrorMessage(message);
	return false;
}

return true;
